export type Surface = 'google_aio'|'chatgpt_search'|'gemini'|'bing_copilot'|'perplexity'|'grok'|'duckduckgo_search_assist';
export type Stage = 'opening'|'preparing'|'submitting'|'waiting'|'capturing';
export interface BrowserConfig {country:string;locale:string;timezone:string;device:'desktop'|'mobile'|'tablet';accountMode?:'signed_out'|'signed_in_private'|'isolated';guestPolicy?:'no_login_v1';egressPolicy?:'unverified'|'canada_fixed'|'country_fixed'}
export interface BrowserTask {planId?:string;slotId:string;prompt:string;surface:Surface;config:BrowserConfig;timeoutSeconds:number;captureScreenshot?:boolean;browserMode?:'silent'|'visible';verifiedCountry:string|null;geoVerificationNote:string;confirmEgress?:(proof:EgressProof)=>void}
export interface EgressProof {country:string;fingerprint:string;verifiedAt:string;provider:'cloudflare_trace'}
export interface Capture {slotId:string;prompt:string;status:'observed'|'not_triggered'|'unavailable'|'error'|'cancelled';reason:string;restriction:'none'|'login'|'captcha'|'rate_limit'|'region';observedAt:string;answer:string;citations:{url:string;title?:string;placement?:'answer_link'|'source_panel'}[];model:string;sourceUrl?:string;sessionRef?:string;account:'logged_out'|'logged_in'|'unknown';session:'fresh'|'active'|'unknown';privacy?:{mode:'signed_out'|'signed_in_private'|'signed_in_independent';temporaryChat:'verified'|'not_applicable'|'unknown';personalization:'disabled'|'enabled'|'unknown';newConversation:boolean};exitCountry:string|null;geo:'ip_observed'|'unverified';locale:string;timezone:string;device:'desktop'|'mobile'|'tablet'|'unknown';geolocation:'denied'|'real'|'unknown';searchMode:'natural'|'explicit_search'|'unknown';collectionMode:'manual_capture'|'browser_capture'|'fixture';retrievalUsed:boolean|null;artifact:{mime:'image/png'|'image/jpeg'|'image/webp'|'text/plain';base64:string}|null;geoVerificationNote?:string;browser?:{name:'Google Chrome';mode?:'silent'|'visible';version:string;extractorVersion:string;answerComplete:boolean;citationsComplete:boolean;notes:string[];unresolvedCitations?:number;citationOverflow?:number;citationControls?:number;citationControlsOpened?:number;egress?:EgressProof}}
export interface GuestReadiness {checkedAt:string;status:'ready'|'restricted'|'unknown';restriction:Capture['restriction'];account:Capture['account'];sourceUrl:string;reason:string;answer:'not_tested';citations:'not_tested';browserMode?:'silent'|'visible'}
export interface Collector {available():{available:boolean;message:string};collect(task:BrowserTask,signal:AbortSignal,stage:(value:Stage)=>void):Promise<Capture>;show():Promise<void>;close():Promise<void>;closePlanSessions(planId:string):Promise<void>;prepareSession(task:{planId:string;surface:Surface;config:BrowserConfig}):Promise<unknown>;verifySession(planId:string,surface:Surface):Promise<unknown>;sessions():{planId:string;surface:string;verified:boolean}[];ready(planId:string,surfaces:string[]):boolean;savedSession(surface:Surface):boolean;canRestore(planId:string,surfaces:string[]):boolean;forgetSession(surface:Surface):Promise<{forgotten:boolean}>;inspectGuest(task:{planId:string;surface:Surface;config:BrowserConfig;browserMode:'silent'|'visible'},signal:AbortSignal):Promise<GuestReadiness>}
export interface CollectorOptions {profileRoot?:string;accountDiagnostics?:((record:unknown)=>void)&{enabled?:()=>boolean}}
export function createCollector(options?:CollectorOptions):Collector;
export const createChromeCollector:typeof createCollector;
export interface Evidence {kind:'answerpouch.capture';schemaVersion:1;collector:{name:'AnswerPouch'|'CiteSnap';version:string;sourceManifestSha256:string};task:BrowserTask;capture:Capture;hash:string}
/** Version 1 evidence supports strict signed-out tasks; validation rejects broader modes. */
export function createEvidence(task:BrowserTask,capture:Capture):Evidence;
export function verifyEvidence(envelope:unknown):{valid:true;schemaVersion:1;status:Capture['status'];restriction:Capture['restriction']};
export const taskSchema:import('zod').ZodType;
